-- Lot 215 : payloads 421 a 450 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-231","moteur":"chatgpt","payload":"[RaccourcIA — /doctorportrait]\n\nMISSION\nCréer un portrait professionnel pour un praticien. Conserve identité, tenue et spécialité fournies. Ne crée ni titre, ni badge officiel, ni acte médical absent du contexte.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portrait médical » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Conserve identité, tenue et spécialité fournies. Ne crée ni titre, ni badge officiel, ni acte médical absent du contexte. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"fa22fc8f69b3f02dd191b8c4973d24e37d4379a80283ca6ce73331cd5ff64a95"},{"ref":"RCI-IMG-231","moteur":"claude","payload":"[RaccourcIA — /doctorportrait]\n\nMISSION\nCréer un portrait professionnel pour un praticien. Conserve identité, tenue et spécialité fournies. Ne crée ni titre, ni badge officiel, ni acte médical absent du contexte.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portrait médical » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Conserve identité, tenue et spécialité fournies. Ne crée ni titre, ni badge officiel, ni acte médical absent du contexte. Le format par défaut est 4:5 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve l’identité, la structure du visage, la carnation, l’âge apparent et les proportions corporelles, sauf changement explicitement demandé.\n\nÉVITER\nÉvite visage remplacé, peau lissée artificiellement, morphologie modifiée, doigts incorrects, pose impossible et changement ethnique. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. fidélité; impact; lisibilité; composition; lumière; perspective; matière; texte; absence d’artefacts Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"c385f2a41fc55c045c13de93f365f7fbcc798f8dcdafcf2f9130a9b450076d12"},{"ref":"RCI-IMG-231","moteur":"gemini","payload":"[RaccourcIA — /doctorportrait]\n\nMISSION\nCréer un portrait professionnel pour un praticien. Conserve identité, tenue et spécialité fournies. Ne crée ni titre, ni badge officiel, ni acte médical absent du contexte.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quel usage ou style doit guider la transformation du portrait ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Portrait médical » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Conserve identité, tenue et spécia